import json, os
for f, name in [('results/phase1_fixed_mix_r025_seed44_results.json', 'exp_015'), ('results/phase1_fixed_mix_r030_seed44_results.json', 'exp_016')]:
    try:
        if not os.path.exists(f):
            # try finding similar files
            import glob
            candidates = glob.glob('results/*r025*') if 'r025' in f else glob.glob('results/*r030*')
            print(f'{name}: FILE_NOT_FOUND, candidates={candidates}')
            continue
        data = json.load(open(f))
        if isinstance(data, list):
            print(f'{name}: list format, len={len(data)}')
            # try to find gen info
            if len(data) > 0:
                last = data[-1]
                if isinstance(last, dict):
                    gen_key = last.get('generation', last.get('gen', 'unknown'))
                    print(f'{name}: last_entry gen={gen_key}, total_entries={len(data)}')
        elif isinstance(data, dict):
            gens = sorted([k for k in data.keys() if k.startswith('gen_')], key=lambda x: int(x.split('_')[1]))
            last = gens[-1] if gens else 'none'
            print(f'{name}: last_gen={last}, total_gens={len(gens)}')
    except Exception as e:
        print(f'{name}: ERROR - {e}')
